def col(n,t,d,null=False,default=None,ref=None,check=None,gen=None):
    return dict(name=n,type=t,description=d,nullable=null,default=default,reference=ref,check=check,generated=gen)
def f(n,target,d=None,null=False): return col(n,'BIGINT UNSIGNED',d or 'Referencia a '+target,null,ref=target+'.id')
def txt(n,d,size=255,null=False):return col(n,f'VARCHAR({size})',d,null)
def tm(n,d,null=False):return col(n,'DATETIME(6)',d,null)
def b(n,d,default=0):return col(n,'TINYINT UNSIGNED',d,default=str(default),check=f'`{n}` IN (0,1)')
def e(n,values,d,default=None):
    return col(n,'VARCHAR(32)',d+' Valores: '+', '.join(values)+'.',default=None if default is None else "'"+default+"'",check=f'`{n}` IN ('+','.join("'"+x+"'" for x in values)+')')
def num(n,d,default=None,null=False):return col(n,'INT UNSIGNED',d,null,default)
def money(n,d,null=False):return col(n,'DECIMAL(12,2)',d,null,check=f'`{n}` >= 0')
def js(n,d,null=False):return col(n,'JSON',d,null)
def body(n,d,null=False):return col(n,'TEXT',d,null)
def ver():return num('version','Control de concurrencia optimista; incrementa en cada cambio.','1')
def generated(n,t,expr,d):return col(n,t,d,True,gen=expr)
def T(name,kind,module,description,fields,uq=(),ix=(),checks=(),rules=(),privacy='Restringido por rol y pertenencia.',stamp='both',pk=None,identity=True):
    fields=list(fields)
    if identity:fields.insert(0,col('id','BIGINT UNSIGNED','Identificador interno inmutable.',default='AUTO_INCREMENT'))
    if stamp:fields.append(col('created_at','DATETIME(6)','Fecha de creación UTC.',default='CURRENT_TIMESTAMP(6)'))
    if stamp=='both':fields.append(col('updated_at','DATETIME(6)','Último cambio UTC; lo actualiza la aplicación.',default='CURRENT_TIMESTAMP(6)'))
    obj=dict(name=name,classification=kind,module=module,description=description,columns=fields,primary_key=list(pk or ['id']),unique=[list(x) for x in uq],indexes=[list(x) for x in ix],checks=list(checks),application_rules=list(rules),privacy=privacy)
    tables.append(obj);return obj

